package net.minecraft.server.level;import net.minecraft.core.*;import net.minecraft.server.*;import net.minecraft.world.*;import net.minecraft.world.level.block.state.*;public class ServerLevel{private final MinecraftServer server;public final java.util.Map<BlockPos,Container> containers=new java.util.HashMap<>();private final MinecraftServer.Storage storage=new MinecraftServer.Storage();public boolean loaded=true;public String dimension="minecraft:overworld";public ServerLevel(MinecraftServer server){this.server=server;}public MinecraftServer getServer(){return server;}public MinecraftServer.Storage getDataStorage(){return storage;}public boolean hasChunkAt(BlockPos p){return loaded;}public BlockState getBlockState(BlockPos p){return new BlockState(containers.containsKey(p));}public Key dimension(){return new Key(dimension);}public record Key(String value){public String location(){return value;}}}
